#include <bit>
#include <cstdint>
#include <iostream>
#include <print>
#include <string>

class SmallSet {
public:
    void add(int x) {
        if (valid(x)) {
            bits_ |= bit(x);
        }
    }

    void remove(int x) {
        if (valid(x)) {
            bits_ &= ~bit(x);
        }
    }

    bool contains(int x) const {
        return valid(x) && (bits_ & bit(x)) != 0;
    }

    int size() const {
        return std::popcount(bits_);
    }

    std::string to_string() const {
        std::string out = "{";
        for (int i = 0; i < 64; i++) {
            if (contains(i)) {
                out += out.size() > 1 ? ", " : "";
                out += std::to_string(i);
            }
        }
        return out + "}";
    }

private:
    static bool valid(int x) {
        return x >= 0 && x < 64;
    }

    static std::uint64_t bit(int x) {
        return std::uint64_t{1} << x;
    }

    std::uint64_t bits_ = 0;
};

int main() {
    SmallSet set;
    std::string command;
    while (std::cin >> command) {
        if (command == "size") {
            std::println("{}", set.size());
        } else if (command == "print") {
            std::println("{}", set.to_string());
        } else {
            int x;
            std::cin >> x;
            if (command == "add") {
                set.add(x);
            } else if (command == "remove") {
                set.remove(x);
            } else {
                std::println("{}", set.contains(x) ? "да" : "нет");
            }
        }
    }
    return 0;
}

