class Celsius {
public:
    explicit Celsius(double c) : kelvin_(c + 273.15) {}
    double value() const { return kelvin_ - 273.15; }
    void warm(double d) { kelvin_ += d; }

private:
    double kelvin_;
};

int main() {
    Celsius t(20);
    t.warm(5);
    std::println("{:.1f}", t.value());
    return 0;
}
